package com.enterprise.scheduler;

import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import java.util.concurrent.TimeUnit;

@Component
public class EnterpriseTaskScheduler {

    // Runs every 5 seconds, ignoring execution duration of the method body
    @Scheduled(fixedRate = 5000, timeUnit = TimeUnit.MILLISECONDS)
    public void processHeartbeat() {
        System.out.println("Heartbeat executed at fixed rate.");
    }

    // Runs every 5 seconds AFTER the previous execution has fully completed
    @Scheduled(fixedDelay = 5000)
    public void pollDatabaseQueue() {
        System.out.println("Polling database queue post-completion.");
    }

    // Runs at 02:00 AM every single day using a standard Cron expression
    @Scheduled(cron = "0 0 2 * * ?")
    public void executeNightlyBatchJob() {
        System.out.println("Executing heavy nightly batch job...");
    }
}
